def remove_control_characters(s):
    table = remove_control_characters.__dict__.get("_table")
    if table is None:
        import sys
        table = dict.fromkeys(
            cp for cp in range(sys.maxunicode + 1)
            if unicodedata.category(chr(cp))[0] == "C"
        )
        remove_control_characters._table = table
    return s.translate(table)

def remove_control_characters(s):
    category = unicodedata.category
    return "".join(ch for ch in s if category(ch)[0]!="C")

