def get_feed_docids(feed, namespace, doc_type):
    with open(feed, "r", encoding='utf-8') as f:
        feed_json = json.load(f)
    if doc_type == "doc":
        prefix = "id:{0}:doc::".format(namespace)
        return set([prefix + find(doc, "fields.namespace") + find(doc, "fields.path") for doc in feed_json])
    elif doc_type == "term":
        prefix = "id:{0}:term::".format(namespace)
        return set([prefix + str(find(doc, "fields.hash")) for doc in feed_json])
    elif doc_type == "paragraph":
        return set([doc['put'] for doc in feed_json])
